import { Alert, Card, Col, Progress, Row, Spin, Statistic, Table, Typography } from 'antd';
import type { ColumnsType } from 'antd/es/table';
import { useEffect, useMemo, useState } from 'react';
import type { DashboardOverview, DisciplineStat, SubsystemSummary } from '../api/dashboard';
import { fetchDashboardOverview } from '../api/dashboard';

const formatPercent = (value: number | undefined) =>
  typeof value === 'number' ? `${value.toFixed(1)}%` : '0.0%';

const DashboardPage = () => {
  const [overview, setOverview] = useState<DashboardOverview | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadOverview = async () => {
      try {
        setLoading(true);
        setError(null);
        const data = await fetchDashboardOverview();
        setOverview(data);
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Failed to load dashboard overview';
        setError(message);
      } finally {
        setLoading(false);
      }
    };

    void loadOverview();
  }, []);

  const disciplineColumns: ColumnsType<DisciplineStat> = useMemo(
    () => [
      {
        title: 'Discipline',
        dataIndex: 'discipline',
      },
      {
        title: 'Tags',
        dataIndex: 'tag_total',
        sorter: (a, b) => a.tag_total - b.tag_total,
      },
      {
        title: 'MCR Total',
        dataIndex: 'mcr_total',
        sorter: (a, b) => a.mcr_total - b.mcr_total,
      },
      {
        title: 'MCR Closed',
        dataIndex: 'mcr_closed',
        sorter: (a, b) => a.mcr_closed - b.mcr_closed,
      },
      {
        title: 'Closed %',
        dataIndex: 'mcr_closed_pct',
        render: (value: number) => formatPercent(value),
        sorter: (a, b) => a.mcr_closed_pct - b.mcr_closed_pct,
      },
      {
        title: 'Tags with Punch',
        dataIndex: 'tags_with_punch',
        sorter: (a, b) => a.tags_with_punch - b.tags_with_punch,
      },
    ],
    [],
  );

  const subsystemColumns: ColumnsType<SubsystemSummary> = useMemo(
    () => [
      {
        title: 'System',
        dataIndex: 'sys_code',
      },
      {
        title: 'Subsystem',
        dataIndex: 'subsys_code',
      },
      {
        title: 'Discipline',
        dataIndex: 'discipline',
      },
      {
        title: 'MCR Total',
        dataIndex: 'mcr_total',
        sorter: (a, b) => a.mcr_total - b.mcr_total,
      },
      {
        title: 'MCR Closed',
        dataIndex: 'mcr_closed',
        sorter: (a, b) => a.mcr_closed - b.mcr_closed,
      },
      {
        title: 'Progress %',
        dataIndex: 'progress_pct',
        render: (value: number) => (
          <div style={{ minWidth: 120 }}>
            <Typography.Text strong>{formatPercent(value)}</Typography.Text>
            <Progress
              percent={parseFloat(value.toFixed(1))}
              size="small"
              showInfo={false}
              status="active"
              style={{ marginTop: 8 }}
            />
          </div>
        ),
        sorter: (a, b) => a.progress_pct - b.progress_pct,
      },
      {
        title: 'Open MCR',
        dataIndex: 'open_mcr',
        sorter: (a, b) => a.open_mcr - b.open_mcr,
      },
      {
        title: 'Tags with Punch',
        dataIndex: 'tags_with_punch',
        sorter: (a, b) => a.tags_with_punch - b.tags_with_punch,
      },
    ],
    [],
  );

  if (loading && !overview) {
    return (
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: 320 }}>
        <Spin size="large" />
      </div>
    );
  }

  return (
    <div>
      <Typography.Title level={3} style={{ marginBottom: 24 }}>
        Dashboard Overview
      </Typography.Title>

      {error && (
        <Alert
          type="error"
          message="Unable to load dashboard overview"
          description={error}
          showIcon
          style={{ marginBottom: 24 }}
        />
      )}

      {overview && (
        <Spin spinning={loading} tip="Refreshing...">
          <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
            <Col xs={24} sm={12} md={6}>
              <Card>
                <Statistic title="Total Tags" value={overview.total_tags} />
              </Card>
            </Col>
            <Col xs={24} sm={12} md={6}>
              <Card>
                <Statistic title="MCR Closed" value={overview.mcr_closed_pct.toFixed(1)} suffix="%" />
              </Card>
            </Col>
            <Col xs={24} sm={12} md={6}>
              <Card>
                <Statistic title="MCR Open" value={overview.mcr_open} />
              </Card>
            </Col>
            <Col xs={24} sm={12} md={6}>
              <Card>
                <Statistic title="Tags with Punch" value={overview.tags_with_punch} />
              </Card>
            </Col>
          </Row>

          <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
            <Col xs={24} lg={14}>
              <Card title="Discipline Progress">
                <Table<DisciplineStat>
                  rowKey={(record) => record.discipline}
                  dataSource={overview.discipline_stats}
                  columns={disciplineColumns}
                  pagination={{ pageSize: 10 }}
                />
              </Card>
            </Col>
            <Col xs={24} lg={10}>
              <Card title="Slowest Subsystems">
                <Table<SubsystemSummary>
                  rowKey={(record) => `${record.sys_code}-${record.subsys_code}`}
                  dataSource={overview.slowest_subsystems}
                  columns={subsystemColumns}
                  pagination={{ pageSize: 10 }}
                />
              </Card>
            </Col>
          </Row>

          <Row gutter={[16, 16]}>
            <Col span={24}>
              <Card title="Punch-heavy Subsystems">
                <Table<SubsystemSummary>
                  rowKey={(record) => `${record.sys_code}-${record.subsys_code}`}
                  dataSource={overview.punch_heavy_subsystems}
                  columns={subsystemColumns}
                  pagination={{ pageSize: 10 }}
                />
              </Card>
            </Col>
          </Row>
        </Spin>
      )}
    </div>
  );
};

export default DashboardPage;
