  open_mcr: number;
}

export interface DashboardOverview {
  total_subsystems: number;
  total_tags: number;
  total_mcr: number;
  mcr_closed: number;
  mcr_closed_pct: number;
  mcr_open: number;
  tags_with_punch: number;
  discipline_stats: DisciplineStat[];
  slowest_subsystems: SubsystemSummary[];
  punch_heavy_subsystems: SubsystemSummary[];
}

export async function fetchDashboardOverview(): Promise<DashboardOverview> {
  const res = await axiosInstance.get<DashboardOverview>('/dashboard/overview');
  return res.data;
